    private readonly Dictionary<string, CodexSidebarMenuButton> _pageButtonsById = new(StringComparer.Ordinal);
    private readonly Dictionary<string, Control> _pageContentById = new(StringComparer.Ordinal);
    private readonly List<(Border Border, string? BackgroundKey, string? BorderKey)> _themedBorders = [];
    private readonly Grid _pageSurface = new();
    private readonly Border _topbar = new();
    private readonly CodexText _topbarTitle = Text(string.Empty, CodexTextRole.Subtitle);
    private readonly CodexText _topbarMeta = Muted(string.Empty);
    private readonly CodexButton _lightThemeButton = ThemeButton("Light");
    private readonly CodexButton _darkThemeButton = ThemeButton("Dark");
    private readonly CodexButton _customThemeButton = ThemeButton("Custom");
    private CodexSwitchThemeMode _currentMode = CodexSwitchThemeMode.Light;
    private DocsPage _activePage;

    public MainWindow()
    {
        _activePage = Categories[0].Pages[0];
        _lightThemeButton.Click += (_, _) => ApplyTheme(CodexSwitchThemeMode.Light);
        _darkThemeButton.Click += (_, _) => ApplyTheme(CodexSwitchThemeMode.Dark);
        _customThemeButton.Click += (_, _) => ApplyTheme(CodexSwitchThemeMode.Custom);

        Title = "CodexSwitchUI Docs";
        Width = 1440;
        Height = 920;
        MinWidth = 1120;
        MinHeight = 740;
        Background = ThemeBrush(CodexSwitchResourceKeys.BackgroundBrush);

        Content = BuildDocsShell();
        NavigateToPage(_activePage.Id);
    }

    private static DocsPage Page(
        string id,
        string category,
        string title,
        string description,
        string samplePath,
        Func<Control> preview,
        IReadOnlyList<string> behaviorNotes)
    {
        return new DocsPage(
            id,
            category,
            title,
            description,
            samplePath,
            preview,
            ExampleCasesFor(id, samplePath, preview),
            ["Examples", "AXAML", "States", "Events"],
            behaviorNotes,
            StateCasesFor(id),
            EventCasesFor(id));
    }

