    private static IReadOnlyList<DocsEventCase> EventCasesFor(string pageId)
    {
        return pageId switch
        {
            "layout.application-shell" =>
            [
                Event("Menu click", "Updates active page state without rebuilding the sidebar."),
                Event("Group action", "Runs the action button while preserving hover and focus feedback."),
                Event("Theme switch", "Repaints sidebar and section chrome through theme resources.")
