    private static DocsStateCase State(string state, string surface, string contract)
    {
        return new DocsStateCase(state, surface, contract);
    }

    private static DocsEventCase Event(string input, string expected)
    {
        return new DocsEventCase(input, expected);
    }

    private Control BuildDocsShell()
    {
        var root = new Grid
        {
            ColumnDefinitions =
            {
                new ColumnDefinition(new GridLength(292)),
                new ColumnDefinition(GridLength.Star)
            },
            RowDefinitions =
            {
                new RowDefinition(new GridLength(72)),
                new RowDefinition(GridLength.Star)
            }
        };

        var sidebar = BuildPageNavigation();
        Grid.SetRowSpan(sidebar, 2);
        root.Children.Add(sidebar);

        _topbar.Child = BuildTopbar();
        Grid.SetColumn(_topbar, 1);
        root.Children.Add(_topbar);

        var contentScroll = new ScrollViewer
        {
            Padding = new Thickness(34, 30, 34, 52),
            Content = _pageSurface
        };
        Grid.SetColumn(contentScroll, 1);
        Grid.SetRow(contentScroll, 1);
        root.Children.Add(contentScroll);

        return root;
    }

    private Control BuildPageNavigation()
    {
        _pageButtonsById.Clear();

        var nav = new StackPanel
        {
            Spacing = 20,
            Margin = new Thickness(18, 22)
        };

        nav.Children.Add(new StackPanel
        {
            Spacing = 4,
            Children =
            {
                Text("CodexSwitchUI", CodexTextRole.Title),
                Muted("Component documentation, source examples, and behavior states.")
            }
        });

        nav.Children.Add(new CodexSeparator());

        foreach (var category in Categories)
        {
            var group = new StackPanel { Spacing = 6 };
            group.Children.Add(new CodexSidebarGroupLabel { Content = category.Title });

            var pages = new StackPanel { Spacing = 3 };
            foreach (var page in category.Pages)
            {
                var button = new CodexSidebarMenuButton
                {
                    Content = page.Title,
                    Badge = page.SamplePath.EndsWith(".axaml", StringComparison.Ordinal) ? "AXAML" : null,
                    HorizontalAlignment = HorizontalAlignment.Stretch
                };
                button.Click += (_, _) => NavigateToPage(page.Id);
                _pageButtonsById[page.Id] = button;
                pages.Children.Add(button);
            }

            group.Children.Add(new CodexSidebarGroupContent { Content = pages });
            nav.Children.Add(group);
        }

        return ThemedBorder(CodexSwitchResourceKeys.CardBrush, CodexSwitchResourceKeys.BorderBrush, new Thickness(0, 0, 1, 0), child: new ScrollViewer { Content = nav });
    }

    private Border ThemedBorder(
        string? backgroundKey,
        string? borderKey,
        Thickness borderThickness,
        CornerRadius? cornerRadius = null,
        Thickness? padding = null,
        Control? child = null)
    {
        var border = new Border
        {
            BorderThickness = borderThickness,
            CornerRadius = cornerRadius ?? default,
            Padding = padding ?? default,
            Child = child
        };

        BindThemeBorder(border, backgroundKey, borderKey);
        return border;
    }

    private void BindThemeBorder(Border border, string? backgroundKey, string? borderKey)
    {
        _themedBorders.Add((border, backgroundKey, borderKey));
        ApplyThemeBorder(border, backgroundKey, borderKey);
    }

    private static void ApplyThemeBorder(Border border, string? backgroundKey, string? borderKey)
    {
        if (backgroundKey is not null)
        {
            border.Background = ThemeBrush(backgroundKey);
        }

        if (borderKey is not null)
        {
            border.BorderBrush = ThemeBrush(borderKey);
        }
    }

    private Control BuildTopbar()
    {
        var grid = new Grid
        {
            ColumnDefinitions =
            {
                new ColumnDefinition(GridLength.Star),
                new ColumnDefinition(GridLength.Auto)
            },
            Margin = new Thickness(28, 0)
        };

        var heading = new StackPanel
        {
            Spacing = 2,
            VerticalAlignment = VerticalAlignment.Center,
            Children =
            {
                _topbarTitle,
                _topbarMeta
            }
        };
        grid.Children.Add(heading);

        var actions = new StackPanel
        {
            Orientation = Orientation.Horizontal,
            Spacing = 8,
            HorizontalAlignment = HorizontalAlignment.Right,
            VerticalAlignment = VerticalAlignment.Center,
            Children =
            {
                _lightThemeButton,
                _darkThemeButton,
                _customThemeButton
            }
        };
        Grid.SetColumn(actions, 1);
        grid.Children.Add(actions);

        return ThemedBorder(CodexSwitchResourceKeys.CardBrush, CodexSwitchResourceKeys.BorderBrush, new Thickness(0, 0, 0, 1), child: grid);
    }

    private static CodexButton ThemeButton(string label)
    {
        return new CodexButton
        {
            Content = label,
            Size = CodexControlSize.Small
        };
    }

    private void RefreshTopbar(DocsPage page)
    {
        _topbarTitle.Text = page.Title;
        _topbarMeta.Text = $"{page.Category} / {page.SamplePath}";
        _lightThemeButton.Variant = _currentMode == CodexSwitchThemeMode.Light ? CodexControlVariant.Default : CodexControlVariant.Secondary;
        _darkThemeButton.Variant = _currentMode == CodexSwitchThemeMode.Dark ? CodexControlVariant.Default : CodexControlVariant.Secondary;
        _customThemeButton.Variant = _currentMode == CodexSwitchThemeMode.Custom ? CodexControlVariant.Default : CodexControlVariant.Secondary;
    }

    private void NavigateToPage(string pageId)
    {
        var page = Categories.SelectMany(category => category.Pages).FirstOrDefault(candidate => candidate.Id == pageId)
            ?? Categories[0].Pages[0];

        _activePage = page;
        RefreshSidebarSelection();
        RefreshTopbar(page);
        ShowCachedPage(_pageSurface, _pageContentById, page.Id, () => BuildPageContent(page));
    }

    private static void ShowCachedPage(Grid host, Dictionary<string, Control> cache, string pageId, Func<Control> factory)
    {
        if (!cache.TryGetValue(pageId, out var control))
        {
            control = factory();
            control.IsVisible = false;
            cache[pageId] = control;
            host.Children.Add(control);
        }

        foreach (var child in host.Children)
        {
            child.IsVisible = ReferenceEquals(child, control);
        }
    }

    private void RefreshSidebarSelection()
    {
        foreach (var (pageId, button) in _pageButtonsById)
        {
            button.IsActive = pageId == _activePage.Id;
        }
    }

    private Control BuildPageContent(DocsPage page)
    {
        return new StackPanel
        {
            Spacing = 28,
            Children =
            {
                BuildPageHero(page),
                BuildPreviewSection(page),
                BuildStateSection(page)
            }
        };
    }

    private Control BuildPageHero(DocsPage page)
    {
        return new Grid
        {
            ColumnDefinitions =
            {
                new ColumnDefinition(GridLength.Star),
                new ColumnDefinition(GridLength.Auto)
            },
            Children =
            {
                new StackPanel
                {
                    Spacing = 10,
                    Children =
                    {
                        new CodexBadge { Content = page.Category, Variant = CodexControlVariant.Outline },
                        Text(page.Title, CodexTextRole.Title),
                        Muted(page.Description)
                    }
                },
                HeroMeta(page)
            }
        };
    }

    private Control HeroMeta(DocsPage page)
    {
        var stack = new StackPanel
        {
            Spacing = 8,
            HorizontalAlignment = HorizontalAlignment.Right,
            Children =
            {
                new CodexBadge { Content = "independent page", Variant = CodexControlVariant.Success },
                new CodexBadge { Content = "code copy", Variant = CodexControlVariant.Secondary },
                new CodexBadge { Content = page.SamplePath, Variant = CodexControlVariant.Outline }
            }
        };
        Grid.SetColumn(stack, 1);
        return stack;
    }

    private Control BuildPreviewSection(DocsPage page)
    {
        var stack = new StackPanel
        {
            Spacing = 12,
            Children =
            {
                SectionHeader("Examples", "Rendered component cases with inline AXAML for the current case.")
            }
        };

        foreach (var example in page.Examples)
        {
            stack.Children.Add(PreviewPanel(BuildInlineExample(example)));
        }

        return stack;
    }

    private Control BuildInlineExample(DocsExampleCase example)
    {
        var codeBlocks = new StackPanel
        {
            Spacing = 12,
            IsVisible = false
        };
        foreach (var codeSample in example.CodeSamples)
        {
            codeBlocks.Children.Add(new DocsCodeBlock
            {
                Title = codeSample.Title,
                Code = DocsCodeSamples.Load(codeSample.SamplePath)
            });
        }

        var toggleCode = new CodexButton
        {
            Content = "Show code",
            Size = CodexControlSize.Small,
            Variant = CodexControlVariant.Secondary,
            HorizontalAlignment = HorizontalAlignment.Left
        };
        toggleCode.Click += (_, _) =>
        {
            codeBlocks.IsVisible = !codeBlocks.IsVisible;
            toggleCode.Content = codeBlocks.IsVisible ? "Hide code" : "Show code";
        };

        return new StackPanel
        {
            Spacing = 14,
            Children =
            {
                SectionHeader(example.Title, example.Description),
                example.BuildPreview(),
                toggleCode,
                codeBlocks
            }
        };
    }

    private Control BuildStateSection(DocsPage page)
    {
        return new StackPanel
        {
            Spacing = 12,
            Children =
            {
                SectionHeader("Behavior contract", "Each page records the Web-style state and event paths the component must preserve."),
                PreviewPanel(new StackPanel
                {
                    Spacing = 18,
                    Children =
                    {
                        new Grid
                        {
                            ColumnDefinitions =
                            {
                                new ColumnDefinition(GridLength.Star),
                                new ColumnDefinition(GridLength.Star),
                                new ColumnDefinition(GridLength.Star)
                            },
                            Children =
                            {
                                Stat("Category", page.Category, 0),
                                Stat("Examples", page.Examples.Count.ToString(), 1),
                                Stat("Sections", page.Sections.Count.ToString(), 2)
                            }
                        },
                        BuildBehaviorNotes(page),
                        BuildStateMatrix(page),
                        BuildEventMatrix(page)
                    }
                })
            }
        };
    }

    private Control BuildStateMatrix(DocsPage page)
    {
        var stack = new StackPanel
        {
            Spacing = 10,
            Children =
            {
                SectionHeader("State matrix", "Visual states the page must keep aligned with Web behavior.")
            }
        };

        var grid = new Grid
        {
            ColumnDefinitions =
            {
                new ColumnDefinition(new GridLength(0.9, GridUnitType.Star)),
                new ColumnDefinition(new GridLength(1.05, GridUnitType.Star)),
                new ColumnDefinition(new GridLength(2.1, GridUnitType.Star))
            },
            RowSpacing = 8,
            ColumnSpacing = 8
        };

        AddMatrixHeader(grid, "State", 0);
        AddMatrixHeader(grid, "Surface", 1);
        AddMatrixHeader(grid, "Contract", 2);

        for (var index = 0; index < page.StateCases.Count; index++)
        {
            var state = page.StateCases[index];
            var row = index + 1;
            grid.RowDefinitions.Add(new RowDefinition(GridLength.Auto));
            AddMatrixCell(grid, state.State, row, 0, CodexTextRole.Body);
            AddMatrixCell(grid, state.Surface, row, 1, CodexTextRole.Muted);
            AddMatrixCell(grid, state.Contract, row, 2, CodexTextRole.Muted);
        }

        stack.Children.Add(grid);
        return stack;
    }

    private Control BuildEventMatrix(DocsPage page)
    {
        var stack = new StackPanel
        {
            Spacing = 10,
            Children =
            {
                SectionHeader("Event matrix", "Input paths that should converge with Web component behavior.")
            }
        };

        var grid = new Grid
        {
            ColumnDefinitions =
            {
                new ColumnDefinition(new GridLength(1.1, GridUnitType.Star)),
                new ColumnDefinition(new GridLength(2.6, GridUnitType.Star))
            },
            RowSpacing = 8,
            ColumnSpacing = 8
        };

        AddMatrixHeader(grid, "Input", 0);
        AddMatrixHeader(grid, "Expected behavior", 1);

        for (var index = 0; index < page.EventCases.Count; index++)
        {
            var item = page.EventCases[index];
            var row = index + 1;
            grid.RowDefinitions.Add(new RowDefinition(GridLength.Auto));
            AddMatrixCell(grid, item.Input, row, 0, CodexTextRole.Body);
            AddMatrixCell(grid, item.Expected, row, 1, CodexTextRole.Muted);
        }

        stack.Children.Add(grid);
        return stack;
    }

    private void AddMatrixHeader(Grid grid, string text, int column)
    {
        if (grid.RowDefinitions.Count == 0)
        {
            grid.RowDefinitions.Add(new RowDefinition(GridLength.Auto));
        }

        AddMatrixCell(grid, text, 0, column, CodexTextRole.Subtitle);
    }

    private void AddMatrixCell(Grid grid, string text, int row, int column, CodexTextRole role)
    {
        var cell = ThemedBorder(
            CodexSwitchResourceKeys.CardBrush,
            CodexSwitchResourceKeys.BorderBrush,
            new Thickness(1),
            new CornerRadius(6),
            new Thickness(10, 8),
            Text(text, role));
        Grid.SetRow(cell, row);
        Grid.SetColumn(cell, column);
        grid.Children.Add(cell);
    }

    private Control BuildBehaviorNotes(DocsPage page)
    {
        var stack = new StackPanel { Spacing = 8 };
        foreach (var note in page.BehaviorNotes)
        {
            stack.Children.Add(ThemedBorder(
                CodexSwitchResourceKeys.CardBrush,
                CodexSwitchResourceKeys.BorderBrush,
                new Thickness(1),
                new CornerRadius(6),
                new Thickness(10, 8),
                Muted(note)));
        }

        return stack;
    }

    private static Control BuildOverviewPreview()
    {
        var grid = new Grid
        {
            ColumnDefinitions =
            {
                new ColumnDefinition(GridLength.Star),
                new ColumnDefinition(GridLength.Star),
                new ColumnDefinition(GridLength.Star)
            },
            RowDefinitions =
            {
                new RowDefinition(GridLength.Auto),
                new RowDefinition(GridLength.Auto),
                new RowDefinition(GridLength.Auto)
            },
            ColumnSpacing = 14,
            RowSpacing = 14
        };

        var cells = new[]
        {
            ("Categories", Categories.Length.ToString(), "Grouped navigation"),
            ("Pages", Categories.Sum(category => category.Pages.Count).ToString(), "Independent screens"),
            ("AXAML files", Categories.SelectMany(category => category.Pages).Select(page => page.SamplePath).Distinct().Count().ToString(), "Copied examples"),
            ("Code samples", "Inline", "Expand under each example"),
            ("Layout", "2 columns", "Nav / docs"),
            ("Theme", "Live", "Light, dark, custom")
        };

        for (var index = 0; index < cells.Length; index++)
        {
            var (label, value, note) = cells[index];
            var cell = new StackPanel
            {
                Spacing = 5,
                Children =
                {
                    Muted(label),
                    Text(value, CodexTextRole.Subtitle),
                    Muted(note)
                }
            };
            Grid.SetColumn(cell, index % 3);
            Grid.SetRow(cell, index / 3);
            grid.Children.Add(cell);
        }

        return grid;
    }

