    private static Control BuildSidebarInteractionPreview()
    {
        var status = Muted("Sidebar is expanded.");
        var provider = new CodexSidebarProvider();
        provider.OpenChanged += (_, args) =>
        {
            status.Text = args.IsOpen ? "Sidebar is expanded." : "Sidebar is collapsed.";
        };

        var shortcut = new CodexButton
        {
            Content = "Run Ctrl+B",
            Size = CodexControlSize.Small,
            Variant = CodexControlVariant.Outline
        };
        shortcut.Click += (_, _) =>
        {
            provider.TryHandleShortcut(Key.B, KeyModifiers.Control);
        };

        provider.Content = new Grid
        {
            Height = 380,
            ColumnDefinitions =
            {
                new ColumnDefinition(new GridLength(260)),
                new ColumnDefinition(GridLength.Auto),
                new ColumnDefinition(GridLength.Star)
            },
            ColumnSpacing = 10,
            Children =
            {
                SidebarSurface("Interactive", CodexSidebarVariant.Inset, CodexSidebarCollapsible.Icon),
                GridCell(new CodexSidebarRail(), row: 0, column: 1),
                GridCell(new CodexSidebarInset
                {
                    Content = new CodexSection
                    {
                        Title = "Interaction contract",
                        Description = "Trigger, rail, and shortcut publish one provider state change.",
                        Actions = new StackPanel
                        {
                            Orientation = Orientation.Horizontal,
                            Spacing = 8,
                            Children =
                            {
                                new CodexSidebarTrigger { Content = "Toggle" },
                                shortcut
                            }
                        },
                        Content = new StackPanel
                        {
                            Spacing = 10,
                            Children =
                            {
                                status,
                                SidebarPrimitiveStat("Trigger", "Click", "ToggleOpen"),
                                SidebarPrimitiveStat("Rail", "Click", "ToggleOpen"),
                                SidebarPrimitiveStat("Shortcut", "Ctrl+B", "TryHandleShortcut")
                            }
                        }
                    }
                }, row: 0, column: 2)
            }
        };

        return provider;
    }

