    private static Control BuildApplicationShellInteractionPreview()
    {
        var status = Muted("Active page: Providers.");
        var providerCount = 12;
        var providers = new CodexSidebarMenuButton { Content = "Providers", IsActive = true, Badge = providerCount.ToString() };
        var sessions = new CodexSidebarMenuButton { Content = "Sessions", Badge = "Live" };
        var usage = new CodexSidebarMenuButton { Content = "Usage" };
        var buttons = new[] { providers, sessions, usage };
        var section = new CodexSection
        {
            Title = "Providers",
            Description = "Sidebar navigation swaps content without rebuilding the shell.",
            Actions = new CodexButton { Content = "Add", Size = CodexControlSize.Small },
            Content = new StackPanel
            {
                Spacing = 10,
                Children =
                {
                    ProviderCard("OpenAI", "Primary route", true),
                    ProviderCard("Claude", "Fallback route", false)
                }
            }
        };

        void Select(CodexSidebarMenuButton selected, string title, string description, Control content)
        {
            foreach (var button in buttons)
            {
                button.IsActive = ReferenceEquals(button, selected);
            }

            section.Title = title;
            section.Description = description;
            section.Content = content;
            status.Text = $"Active page: {title}.";
        }

        providers.Click += (_, _) => Select(
            providers,
            "Providers",
            "Sidebar navigation swaps content without rebuilding the shell.",
            new StackPanel
            {
                Spacing = 10,
                Children =
                {
                    ProviderCard("OpenAI", "Primary route", true),
                    ProviderCard("Claude", "Fallback route", false)
                }
            });
        sessions.Click += (_, _) => Select(
            sessions,
            "Sessions",
            "Active button clears siblings and keeps the section action aligned.",
            new CodexCard
            {
                Title = "Live sessions",
                Description = "Provider session rows stay inside the same section slot.",
                Content = new CodexBadge { Content = "3 active", Variant = CodexControlVariant.Success, IsStatusVisible = true }
            });
        usage.Click += (_, _) => Select(
            usage,
            "Usage",
            "The shell keeps sidebar, footer, and page body mounted while content changes.",
            new CodexRankedBarChart
            {
                Width = 420,
                IsCompact = true,
                ItemsSource = RankedBarChartItems()
            });

        var newProvider = new CodexButton
        {
            Content = "New provider",
            Size = CodexControlSize.Small,
            HorizontalAlignment = HorizontalAlignment.Stretch
        };
        newProvider.Click += (_, _) =>
        {
            providerCount++;
            providers.Badge = providerCount.ToString();
            status.Text = $"Provider badge incremented to {providerCount}.";
        };

        return new Grid
        {
            Height = 380,
            ColumnDefinitions =
            {
                new ColumnDefinition(new GridLength(260)),
                new ColumnDefinition(GridLength.Star)
            },
            ColumnSpacing = 18,
            Children =
            {
                new CodexSidebar
                {
                    Content = new StackPanel
                    {
                        Children =
                        {
                            new CodexSidebarHeader
                            {
                                Content = new StackPanel
                                {
                                    Spacing = 2,
                                    Children =
                                    {
                                        Text("CodexSwitch", CodexTextRole.Subtitle),
                                        status
                                    }
                                }
                            },
                            new CodexSidebarContent
                            {
                                Content = new StackPanel
                                {
                                    Spacing = 14,
                                    Children =
                                    {
                                        new CodexSidebarGroup
                                        {
                                            Content = new StackPanel
                                            {
                                                Spacing = 5,
                                                Children =
                                                {
                                                    new CodexSidebarGroupLabel { Content = "Platform" },
                                                    providers,
                                                    sessions,
                                                    usage
                                                }
                                            }
                                        },
                                        new CodexSidebarGroup
                                        {
                                            Content = new StackPanel
                                            {
                                                Spacing = 5,
                                                Children =
                                                {
                                                    new CodexSidebarGroupLabel { Content = "Settings" },
