    private static CodexResizablePanelGroup BuildResizableGroup(
        double width,
        double height,
        Orientation orientation,
        IReadOnlyList<CodexResizablePanel> panels,
        CodexControlSize size = CodexControlSize.Medium,
        bool withHandles = false)
    {
        var group = new CodexResizablePanelGroup
        {
            Width = width,
            Height = height,
            Orientation = orientation,
            Size = size
        };

        for (var index = 0; index < panels.Count; index++)
        {
            group.Children.Add(panels[index]);
            if (index < panels.Count - 1)
            {
                group.Children.Add(new CodexResizableHandle { WithHandle = withHandles });
            }
        }

        return group;
    }

