    private static CodexInputOtp BuildInputOtp(
        string text,
        int maxLength,
        string? pattern,
        CodexControlIntent intent = CodexControlIntent.Default,
        CodexControlSize size = CodexControlSize.Medium,
        bool isInvalid = false,
        bool isEnabled = true,
        int activeIndex = 0,
        int[]? groupSizes = null)
    {
        groupSizes ??= maxLength == 4 ? [4] : [3, Math.Max(0, maxLength - 3)];
        var input = new CodexInputOtp
        {
            Text = text,
            MaxLength = maxLength,
            Pattern = pattern,
            Intent = intent,
            Size = size,
            IsInvalid = isInvalid,
            IsEnabled = isEnabled,
            ActiveIndex = activeIndex
        };

        var index = 0;
        for (var groupIndex = 0; groupIndex < groupSizes.Length; groupIndex++)
        {
            if (groupIndex > 0)
            {
                input.Items.Add(new CodexInputOtpSeparator());
            }

            var group = new CodexInputOtpGroup();
            for (var slot = 0; slot < groupSizes[groupIndex] && index < maxLength; slot++)
            {
                group.Items.Add(new CodexInputOtpSlot { Index = index });
                index++;
            }

            input.Items.Add(group);
        }

        return input;
    }

