    private static Control BuildIconButtonInteractionPreview()
    {
        var status = Muted("Toolbar action: none");
        var pin = new CodexIconButton
        {
            Content = "p",
            IsRound = true,
            Variant = CodexControlVariant.Secondary
        };
        pin.Click += (_, _) =>
        {
            pin.Variant = pin.Variant == CodexControlVariant.Secondary
                ? CodexControlVariant.Default
                : CodexControlVariant.Secondary;
            status.Text = pin.Variant == CodexControlVariant.Default
                ? "Toolbar action: pinned"
                : "Toolbar action: unpinned";
        };

        var refresh = new CodexIconButton
        {
            Content = ">",
            LoadingContent = "..."
        };
        refresh.Click += (_, _) =>
        {
            refresh.IsLoading = !refresh.IsLoading;
            status.Text = refresh.IsLoading
                ? "Toolbar action: refresh loading"
                : "Toolbar action: refresh ready";
        };

        return new Grid
        {
            ColumnDefinitions =
            {
                new ColumnDefinition(GridLength.Star),
                new ColumnDefinition(GridLength.Star)
            },
            RowDefinitions =
            {
                new RowDefinition(GridLength.Auto),
                new RowDefinition(GridLength.Auto)
            },
            ColumnSpacing = 16,
            RowSpacing = 14,
            Children =
            {
                new CodexField
                {
                    Label = "Toolbar actions",
                    Description = "Icon-only actions keep square dimensions while pointer and keyboard activation share the button path.",
                    Content = new StackPanel
                    {
                        Spacing = 10,
                        Children =
                        {
                            status,
                            new StackPanel
                            {
                                Orientation = Orientation.Horizontal,
                                Spacing = 8,
                                Children =
                                {
                                    pin,
                                    refresh,
                                    new CodexIconButton { Content = "...", Variant = CodexControlVariant.Ghost },
                                    new CodexIconButton { Content = "x", Variant = CodexControlVariant.Destructive }
                                }
                            }
                        }
                    }
                },
                GridCell(new CodexField
                {
                    Label = "Round and focus-visible",
                    Description = "Round geometry changes shape only; focus, hover, pressed, and loading behavior stay shared.",
                    Content = new StackPanel
                    {
                        Orientation = Orientation.Horizontal,
                        Spacing = 8,
                        Children =
                        {
                            new CodexIconButton { Content = "+", IsRound = true },
                            new CodexIconButton { Content = "i", IsRound = true, Variant = CodexControlVariant.Secondary },
                            new CodexIconButton { Content = "?", IsRound = true, Variant = CodexControlVariant.Ghost }
                        }
                    }
                }, row: 0, column: 1),
                GridCell(new CodexField
                {
                    Label = "Loading suppression",
                    Description = "Loading icon buttons keep fixed toolbar geometry and suppress repeated activation.",
                    Content = new StackPanel
                    {
                        Orientation = Orientation.Horizontal,
                        Spacing = 8,
                        Children =
                        {
                            new CodexIconButton { Content = ">", IsLoading = true, LoadingContent = "..." },
                            new CodexIconButton { Content = "*", Variant = CodexControlVariant.Secondary, IsLoading = true }
                        }
                    }
                }, row: 1, column: 0),
                GridCell(new CodexField
                {
                    Label = "Disabled guard",
                    Description = "Disabled icon actions stay aligned with enabled toolbar buttons.",
                    Content = new StackPanel
                    {
                        Orientation = Orientation.Horizontal,
                        Spacing = 8,
