    private static Control BuildSelectInteractionPreview()
    {
        var status = Muted("OpenChanged and source-aware ValueChanged update this status.");
        var select = new CodexSelect
        {
            ItemsSource = new[] { "OpenAI", "Claude", "Responses" },
            SelectedIndex = 0,
            IsDropDownOpen = true,
            MinWidth = 240
        };
        select.OpenChanged += (_, args) =>
        {
            status.Text = $"OpenChanged: popup {(args.IsOpen ? "opened" : "closed")} (source={args.Source}).";
        };
        select.ValueChanged += (_, args) =>
        {
            status.Text = $"ValueChanged: {args.OldValue ?? "none"} -> {args.NewValue ?? "none"} (source={args.Source}).";
        };
        var chooseClaude = new CodexButton
        {
            Content = "Claude",
            Size = CodexControlSize.Small,
            Variant = CodexControlVariant.Secondary
        };
        chooseClaude.Click += (_, _) => select.SelectedIndex = 1;
        var closePopup = new CodexButton
        {
            Content = "Close",
            Size = CodexControlSize.Small,
            Variant = CodexControlVariant.Ghost
        };
        closePopup.Click += (_, _) => select.IsDropDownOpen = false;

        return new Grid
        {
            ColumnDefinitions =
            {
                new ColumnDefinition(GridLength.Star),
                new ColumnDefinition(GridLength.Star)
            },
            RowDefinitions =
            {
                new RowDefinition(GridLength.Auto),
                new RowDefinition(GridLength.Auto)
            },
            ColumnSpacing = 16,
            RowSpacing = 14,
            Children =
            {
                new CodexField
                {
                    Label = "Open popup",
                    Description = "Trigger, selected item, popup-open class, OpenChanged, and source-aware ValueChanged share one state path.",
                    Content = new StackPanel
                    {
                        Spacing = 8,
                        Children =
                        {
                            select,
                            status,
                            new StackPanel
                            {
                                Orientation = Orientation.Horizontal,
                                Spacing = 8,
                                Children =
                                {
                                    chooseClaude,
                                    closePopup
                                }
                            }
                        }
                    }
                },
                GridCell(new CodexField
                {
                    Label = "Keyboard target",
                    Description = "Arrow keys and Enter use the native selection model.",
                    Content = new CodexSelect
                    {
                        ItemsSource = new[] { "Primary", "Fallback", "Disabled" },
                        SelectedIndex = 1,
                        MinWidth = 240
                    }
                }, row: 0, column: 1),
                GridCell(new CodexField
                {
                    Label = "Warning intent",
                    Message = "Fallback provider is active.",
