                    Content = new CodexSelect
                    {
                        ItemsSource = new[] { "Primary", "Fallback" },
                        SelectedIndex = 1,
                        Intent = CodexControlIntent.Warning,
                        Size = CodexControlSize.Small,
                        MinWidth = 240
