    private static Control BuildCheckboxInteractionPreview()
    {
        static string FormatCheckedState(bool? value)
        {
            return value switch
            {
                true => "checked",
                false => "unchecked",
                _ => "indeterminate"
            };
        }

        var status = Muted("CheckedStateChanged: routing is checked (source=Programmatic).");
        var routing = new CodexCheckBox { Content = "Enable provider routing", IsChecked = true };
        routing.CheckedStateChanged += (_, args) =>
        {
            status.Text = $"Routing changed from {FormatCheckedState(args.OldValue)} to {FormatCheckedState(args.NewValue)} (source={args.Source}).";
        };

        var sync = new CodexCheckBox { Content = "Sync archived sessions" };
        sync.CheckedStateChanged += (_, args) =>
        {
            status.Text = $"Sync changed from {FormatCheckedState(args.OldValue)} to {FormatCheckedState(args.NewValue)} (source={args.Source}).";
        };

        return new Grid
        {
            ColumnDefinitions =
            {
                new ColumnDefinition(GridLength.Star),
                new ColumnDefinition(GridLength.Star)
            },
            RowDefinitions =
            {
                new RowDefinition(GridLength.Auto),
                new RowDefinition(GridLength.Auto)
            },
            ColumnSpacing = 16,
            RowSpacing = 14,
            Children =
            {
                new CodexField
                {
                    Label = "Pointer toggle",
                    Description = "Pointer release and Space use the same checked path and report source metadata.",
                    Content = new StackPanel
                    {
                        Spacing = 10,
                        Children =
                        {
                            routing,
                            sync,
                            status
                        }
                    }
                },
                GridCell(new CodexField
                {
                    Label = "Three-state cycle",
                    Description = "Indeterminate state keeps its own glyph animation.",
                    Content = new StackPanel
                    {
                        Spacing = 10,
                        Children =
                        {
                            new CodexCheckBox { Content = "Mixed provider selection", IsThreeState = true, IsChecked = null },
                            new CodexCheckBox { Content = "Partially migrated", IsThreeState = true, IsChecked = true, Intent = CodexControlIntent.Warning }
                        }
                    }
                }, row: 0, column: 1),
                GridCell(new CodexField
                {
                    Label = "Keyboard focus target",
                    Description = "Keyboard focus exposes the shared focus-visible ring.",
                    Content = new StackPanel
                    {
                        Spacing = 10,
                        Children =
                        {
                            new CodexCheckBox { Content = "Focus-visible route", Size = CodexControlSize.Large },
                            new CodexCheckBox { Content = "Small dense row", Size = CodexControlSize.Small, IsChecked = true }
                        }
                    }
                }, row: 1, column: 0),
                GridCell(new CodexField
                {
                    Label = "Disabled guard",
                    Description = "Disabled state blocks pointer and keyboard toggles.",
                    Content = new StackPanel
                    {
                        Spacing = 10,
                        Children =
                        {
                            new CodexCheckBox { Content = "Locked on", IsChecked = true, IsEnabled = false },
                            new CodexCheckBox { Content = "Locked off", Intent = CodexControlIntent.Error, IsEnabled = false }
                        }
                    }
                }, row: 1, column: 1)
            }
        };
    }

