    private static Control BuildRadioGroupInteractionPreview()
    {
        var status = Muted("Selected value is balanced.");
        var group = new CodexRadioGroup
        {
            SelectedValue = "balanced",
            Items =
            {
                new CodexRadioGroupItem { Value = "balanced", Content = "Balanced" },
                new CodexRadioGroupItem { Value = "reasoning", Content = "Reasoning" },
                new CodexRadioGroupItem { Value = "latency", Content = "Low latency" }
            }
        };
        group.ValueChanged += (_, args) =>
        {
            status.Text = $"ValueChanged({args.Source}): [{args.OldIndex}] {args.OldValue ?? "none"} -> [{args.NewIndex}] {args.NewValue ?? "none"}.";
        };

        var cycleValue = new CodexButton
        {
            Content = "Cycle value",
            Size = CodexControlSize.Small,
            Variant = CodexControlVariant.Secondary
        };
        cycleValue.Click += (_, _) =>
        {
            group.SelectedValue = group.SelectedValue switch
            {
                "balanced" => "reasoning",
                "reasoning" => "latency",
                _ => "balanced"
            };
        };

        var toggleOrientation = new CodexButton
        {
            Content = "Toggle orientation",
            Size = CodexControlSize.Small,
            Variant = CodexControlVariant.Ghost
        };
        toggleOrientation.Click += (_, _) =>
        {
            group.Orientation = group.Orientation == Orientation.Vertical ? Orientation.Horizontal : Orientation.Vertical;
            status.Text = $"Orientation changed to {group.Orientation}.";
        };

        var toggleLoading = new CodexButton
        {
            Content = "Toggle loading",
            Size = CodexControlSize.Small,
            Variant = CodexControlVariant.Ghost
        };
        toggleLoading.Click += (_, _) =>
        {
            group.IsLoading = !group.IsLoading;
            status.Text = group.IsLoading
                ? "Loading suppresses item activation and keeps the selected value."
                : "Loading cleared; items can update value again.";
        };

        return new Grid
        {
            ColumnDefinitions =
            {
                new ColumnDefinition(GridLength.Star),
                new ColumnDefinition(GridLength.Star)
            },
            RowDefinitions =
            {
                new RowDefinition(GridLength.Auto),
                new RowDefinition(GridLength.Auto)
            },
            ColumnSpacing = 16,
            RowSpacing = 14,
            Children =
            {
                new CodexField
                {
                    Label = "Value and events",
                    Description = "Primary pointer release, Space/Enter, and roving arrows update the same root value with source metadata.",
                    Content = new StackPanel
                    {
                        Spacing = 10,
                        Children =
                        {
                            status,
                            group,
                            new StackPanel
                            {
                                Orientation = Orientation.Horizontal,
                                Spacing = 8,
                                Children =
                                {
                                    cycleValue,
                                    toggleOrientation,
                                    toggleLoading
                                }
                            }
                        }
                    }
                },
                GridCell(RadioGroupField("Loop disabled", new CodexRadioGroup
                {
                    IsLoop = false,
                    SelectedValue = "first",
                    Items =
                    {
                        new CodexRadioGroupItem { Value = "first", Content = "First boundary" },
                        new CodexRadioGroupItem { Value = "middle", Content = "Middle" },
                        new CodexRadioGroupItem { Value = "last", Content = "Last boundary" }
                    }
                }), row: 0, column: 1),
                GridCell(RadioGroupField("Disabled option", new CodexRadioGroup
                {
                    SelectedValue = "primary",
                    Items =
                    {
                        new CodexRadioGroupItem { Value = "primary", Content = "Primary route" },
                        new CodexRadioGroupItem { Value = "blocked", Content = "Disabled route", IsEnabled = false },
                        new CodexRadioGroupItem { Value = "fallback", Content = "Fallback route" }
                    }
                }), row: 1, column: 0),
                GridCell(RadioGroupField("Horizontal keys", new CodexRadioGroup
                {
                    Orientation = Orientation.Horizontal,
                    SelectedValue = "left",
                    Items =
                    {
                        new CodexRadioGroupItem { Value = "left", Content = "Left" },
                        new CodexRadioGroupItem { Value = "center", Content = "Center" },
                        new CodexRadioGroupItem { Value = "right", Content = "Right" }
                    }
                }), row: 1, column: 1)
            }
        };
    }

