                new RowDefinition(GridLength.Auto)
            },
            ColumnSpacing = 16,
            RowSpacing = 14,
            Children =
            {
                new CodexField
                {
                    Label = "Single selection",
                    Description = "Selecting one item clears siblings; pressing it again can clear the value.",
                    Content = new StackPanel
                    {
                        Spacing = 10,
                        Children =
                        {
                            single,
                            singleStatus
                        }
                    }
                },
                GridCell(new CodexField
                {
                    Label = "Multiple selection",
                    Description = "Each item keeps an independent pressed state.",
                    Content = new StackPanel
                    {
