    private static Control BuildSliderInteractionPreview()
    {
        var status = Muted("ValueChanging and ValueCommitted update this status.");
        var valueSlider = new CodexSlider
        {
            Minimum = 0,
            Maximum = 100,
            Value = 48,
            TickFrequency = 1,
            MinWidth = 320
        };
        valueSlider.ValueChanging += (_, args) =>
        {
            status.Text = $"ValueChanging: {args.OldValue:0.##} -> {args.NewValue:0.##}.";
        };
        valueSlider.ValueCommitted += (_, args) =>
        {
            status.Text = $"ValueCommitted ({args.Source}): {args.OldValue:0.##} -> {args.NewValue:0.##}.";
        };

        var setLow = new CodexButton
        {
            Content = "Set 24",
            Size = CodexControlSize.Small,
            Variant = CodexControlVariant.Secondary
        };
        setLow.Click += (_, _) => valueSlider.Value = 24;

        var setHigh = new CodexButton
        {
            Content = "Set 76",
            Size = CodexControlSize.Small,
            Variant = CodexControlVariant.Secondary
        };
        setHigh.Click += (_, _) => valueSlider.Value = 76;

        var commit = new CodexButton
        {
            Content = "Commit",
            Size = CodexControlSize.Small,
            Variant = CodexControlVariant.Ghost
        };
        commit.Click += (_, _) =>
        {
            if (!valueSlider.CommitValue())
            {
                status.Text = $"ValueCommitted skipped: {valueSlider.Value:0.##} is already committed.";
            }
        };

        var keyboardStatus = Muted("Focus the slider, then use Arrow/Page/Home/End.");
        var keyboardSlider = new CodexSlider
        {
            Minimum = 0,
            Maximum = 2,
            Value = 0.8,
            TickFrequency = 0.1,
            Size = CodexControlSize.Large,
            Intent = CodexControlIntent.Success,
            MinWidth = 320
        };
        keyboardSlider.ValueChanging += (_, args) =>
        {
            keyboardStatus.Text = $"ValueChanging: {args.OldValue:0.##} -> {args.NewValue:0.##}.";
        };
        keyboardSlider.ValueCommitted += (_, args) =>
        {
            keyboardStatus.Text = $"ValueCommitted ({args.Source}): {args.OldValue:0.##} -> {args.NewValue:0.##}.";
        };

        return new Grid
        {
            ColumnDefinitions =
            {
                new ColumnDefinition(GridLength.Star),
                new ColumnDefinition(GridLength.Star)
            },
            RowDefinitions =
            {
                new RowDefinition(GridLength.Auto),
                new RowDefinition(GridLength.Auto)
            },
            ColumnSpacing = 16,
            RowSpacing = 14,
            Children =
            {
                new CodexField
                {
                    Label = "Value events",
                    Description = "Primary pointer drag, track click, and host updates raise ValueChanging before ValueCommitted.",
                    Content = new StackPanel
                    {
                        Spacing = 8,
                        Children =
                        {
                            valueSlider,
                            status,
                            new StackPanel
                            {
                                Orientation = Orientation.Horizontal,
                                Spacing = 8,
                                Children =
                                {
                                    setLow,
                                    setHigh,
                                    commit
                                }
                            }
                        }
                    }
                },
                GridCell(new CodexField
                {
                    Label = "Keyboard commit",
                    Description = "Arrow, Page, Home, and End keys update Value and commit on key release.",
                    Content = new StackPanel
                    {
                        Spacing = 8,
                        Children =
                        {
                            keyboardSlider,
                            keyboardStatus
                        }
                    }
                }, row: 0, column: 1),
                GridCell(new CodexField
                {
                    Label = "Vertical direction",
                    Description = "Vertical orientation keeps the same thumb and track contract.",
                    Content = new CodexSlider
                    {
                        Minimum = 0,
                        Maximum = 100,
                        Value = 66,
                        Orientation = Orientation.Vertical,
                        Intent = CodexControlIntent.Warning,
                        Height = 130
                    }
                }, row: 1, column: 0),
                GridCell(new CodexField
                {
                    Label = "Disabled guard",
                    Description = "Disabled sliders keep drag and keyboard changes locked.",
                    Content = new CodexSlider { Minimum = 0, Maximum = 100, Value = 72, IsEnabled = false, MinWidth = 320 }
                }, row: 1, column: 1)
            }
        };
    }

