    private static Control BuildBadgeInteractionPreview()
    {
        var status = Muted("Badge status: healthy.");
        var statusBadge = new CodexBadge
        {
            Content = "Healthy",
            Variant = CodexControlVariant.Success,
            StatusVariant = CodexControlVariant.Success,
            IsStatusVisible = true
        };
        var statusStep = 0;
        var rotateStatus = new CodexButton
        {
            Content = "Rotate status",
            Size = CodexControlSize.Small,
            Variant = CodexControlVariant.Secondary
        };
        rotateStatus.Click += (_, _) =>
        {
            statusStep = (statusStep + 1) % 3;
            switch (statusStep)
            {
                case 1:
                    statusBadge.Content = "Fallback";
                    statusBadge.Variant = CodexControlVariant.Warning;
                    statusBadge.StatusVariant = CodexControlVariant.Warning;
                    status.Text = "Badge status: fallback warning.";
                    break;
                case 2:
                    statusBadge.Content = "Blocked";
                    statusBadge.Variant = CodexControlVariant.Destructive;
                    statusBadge.StatusVariant = CodexControlVariant.Destructive;
                    status.Text = "Badge status: blocked destructive.";
                    break;
                default:
                    statusBadge.Content = "Healthy";
                    statusBadge.Variant = CodexControlVariant.Success;
                    statusBadge.StatusVariant = CodexControlVariant.Success;
                    status.Text = "Badge status: healthy.";
                    break;
            }
        };

        var count = 2;
        var countBadge = new CodexBadge
        {
            Content = "2 routes",
            Variant = CodexControlVariant.Secondary
        };
        var increment = new CodexButton
        {
            Content = "Add route",
            Size = CodexControlSize.Small,
            Variant = CodexControlVariant.Secondary
        };
        increment.Click += (_, _) =>
        {
            count++;
            countBadge.Content = count >= 9 ? "9+ routes" : $"{count} routes";
            status.Text = $"Route badge updated to {countBadge.Content}.";
        };

        var densityBadge = new CodexBadge
        {
            Content = "Medium",
            Size = CodexControlSize.Medium,
            Variant = CodexControlVariant.Outline
        };
        var toggleSize = new CodexButton
        {
            Content = "Toggle size",
            Size = CodexControlSize.Small,
            Variant = CodexControlVariant.Secondary
        };
        toggleSize.Click += (_, _) =>
        {
            densityBadge.Size = densityBadge.Size == CodexControlSize.Small
                ? CodexControlSize.Large
                : densityBadge.Size == CodexControlSize.Large
                    ? CodexControlSize.Medium
                    : CodexControlSize.Small;
            densityBadge.Content = densityBadge.Size.ToString();
            status.Text = $"Badge size changed to {densityBadge.Size}.";
        };

        var linkBadge = new CodexBadge
        {
            Content = "Open provider",
            Variant = CodexControlVariant.Link,
            IsInteractive = true
        };
        linkBadge.Activated += (_, args) =>
        {
            status.Text = $"Link badge activated: source={args.Source}.";
        };

        var linkField = new CodexField
        {
            Label = "Link badge activation",
            Description = "Interactive badges mirror the Web asChild/link case with focus, pointer, keyboard, and source-aware activation.",
            Content = new StackPanel
            {
                Orientation = Orientation.Horizontal,
                Spacing = 10,
                Children =
                {
                    linkBadge,
                    new CodexBadge
                    {
                        Content = "Command blocked",
                        Variant = CodexControlVariant.Outline,
