    private static Control BuildToastInteractionPreview()
    {
        var status = Muted("Toast is open. DismissCommand and close button share the same close path.");
        var undo = new CodexButton
        {
            Content = "Undo",
            Size = CodexControlSize.Small,
            Variant = CodexControlVariant.Secondary
        };
        var primaryToast = new CodexToast
        {
            Icon = "i",
            Title = "Provider switched",
            Description = "Close button, Escape, and DismissCommand close the same mounted surface.",
            Action = undo,
            CloseContent = "Dismiss",
            CloseCommand = new DocsActionCommand(() =>
            {
                status.Text = "CloseCommand executed after the toast moved to the closed state.";
            })
        };
        undo.Click += (_, _) =>
        {
            primaryToast.Variant = CodexControlVariant.Success;
            primaryToast.Title = "Provider restored";
            primaryToast.Description = "Action slot clicked without dismissing the toast.";
            status.Text = "Undo action clicked; toast remains open and switched to success.";
        };

        var dismiss = new CodexButton
        {
            Content = "Dismiss command",
            Size = CodexControlSize.Small,
            Variant = CodexControlVariant.Secondary
        };
        dismiss.Click += (_, _) =>
        {
            if (primaryToast.DismissCommand?.CanExecute(null) == true)
            {
                primaryToast.DismissCommand.Execute(null);
            }
        };

        var reopen = new CodexButton
        {
            Content = "Reopen",
            Size = CodexControlSize.Small,
            Variant = CodexControlVariant.Outline
        };
        reopen.Click += (_, _) =>
        {
            primaryToast.IsOpen = true;
            primaryToast.Variant = CodexControlVariant.Default;
            primaryToast.Title = "Provider switched";
            primaryToast.Description = "Close button, Escape, and DismissCommand close the same mounted surface.";
            status.Text = "Toast reopened; open class restored.";
        };

        var manualToast = new CodexToast
        {
            Icon = "!",
            Title = "Manual dismissal policy",
            Description = "Escape is ignored because host code owns this notification.",
            Variant = CodexControlVariant.Warning,
            CloseOnEscape = false,
            CloseContent = "Manual"
        };
        var manualDismiss = new CodexButton
        {
            Content = "Manual close",
            Size = CodexControlSize.Small,
            Variant = CodexControlVariant.Secondary
        };
        manualDismiss.Click += (_, _) =>
        {
            manualToast.IsOpen = !manualToast.IsOpen;
            status.Text = manualToast.IsOpen
                ? "Manual toast reopened without changing Escape policy."
                : "Manual toast closed by host-owned state change.";
        };

        var closedToast = new CodexToast
        {
            Title = "Closed exit state",
            Description = "Closed class stays inspectable for exit motion verification.",
            Variant = CodexControlVariant.Destructive,
            IsOpen = false
        };
        var toggleClosed = new CodexButton
        {
            Content = "Toggle closed sample",
            Size = CodexControlSize.Small,
            Variant = CodexControlVariant.Secondary
        };
        toggleClosed.Click += (_, _) =>
        {
            closedToast.IsOpen = !closedToast.IsOpen;
            status.Text = closedToast.IsOpen
                ? "Closed sample reopened; open class applied."
                : "Closed sample dismissed; exit class applied.";
        };

        return new Grid
        {
            ColumnDefinitions =
            {
                new ColumnDefinition(GridLength.Star),
                new ColumnDefinition(GridLength.Star)
            },
            RowDefinitions =
            {
                new RowDefinition(GridLength.Auto),
                new RowDefinition(GridLength.Auto)
            },
            ColumnSpacing = 16,
            RowSpacing = 14,
            Children =
            {
                new CodexField
                {
                    Label = "Dismiss command path",
                    Description = "Close button, Escape, and DismissCommand converge on one close callback.",
                    Content = new StackPanel
                    {
                        Spacing = 10,
                        Children =
                        {
                            status,
                            primaryToast,
                            new StackPanel
                            {
                                Orientation = Orientation.Horizontal,
                                Spacing = 8,
                                Children =
                                {
                                    dismiss,
                                    reopen
                                }
                            }
                        }
                    }
                },
                GridCell(new CodexField
                {
                    Label = "Manual Escape policy",
                    Description = "CloseOnEscape=false keeps keyboard dismissal under host control.",
                    Content = new StackPanel
                    {
                        Spacing = 10,
                        Children =
                        {
                            manualToast,
                            manualDismiss
                        }
                    }
                }, row: 0, column: 1),
                GridCell(new CodexField
                {
                    Label = "Action without dismissal",
                    Description = "The action slot can mutate content while the toast remains open.",
                    Content = new CodexToast
                    {
                        Icon = "i",
                        Title = "Usage refreshed",
                        Description = "Action and close controls are independent slots.",
                        Action = new CodexButton
                        {
                            Content = "View",
                            Size = CodexControlSize.Small,
                            Variant = CodexControlVariant.Secondary
                        },
                        CloseContent = "Close"
                    }
                }, row: 1, column: 0),
                GridCell(new CodexField
                {
                    Label = "Closed exit state",
                    Description = "Open and closed classes can be toggled without removing the toast from layout.",
                    Content = new StackPanel
                    {
                        Spacing = 10,
                        Children =
                        {
                            closedToast,
                            toggleClosed
                        }
                    }
                }, row: 1, column: 1)
            }
        };
    }

