    private static Control BuildTabsInteractionPreview()
    {
        var status = Muted("ValueChanged reports value and source metadata.");
        var valueTabs = new CodexTabs
        {
            Items =
            {
                new CodexTabItem { Header = "Preview", Value = "preview", Content = Muted("Preview content") },
                new CodexTabItem { Header = "Code", Value = "code", Content = Muted("Arrow keys move selection.") },
                new CodexTabItem { Header = "Disabled", Value = "disabled", IsEnabled = false, Content = Muted("Skipped by navigation.") },
                new CodexTabItem { Header = "Events", Value = "events", Content = Muted("End selects the final enabled tab.") }
            }
        };
        valueTabs.SelectedValue = "code";
        valueTabs.ValueChanged += (_, args) =>
        {
            status.Text = $"ValueChanged: {args.OldValue ?? "none"} -> {args.NewValue ?? "none"} ({args.Source}).";
        };
        var selectPreview = new CodexButton
        {
            Content = "Preview",
            Size = CodexControlSize.Small,
