                new CodexTabItem { Header = "Home", Value = "home", Content = Muted("Manual mode starts here.") },
                new CodexTabItem { Header = "State", Value = "state", Content = Muted("Arrow keys move focus without changing value.") },
                new CodexTabItem { Header = "Disabled", Value = "disabled", IsEnabled = false },
                new CodexTabItem { Header = "End", Value = "end", Content = Muted("Enter or Space activates the focused trigger.") }
