    private static Control BuildMenubarInteractionPreview()
    {
        var status = Muted("ItemSelected: ready.");
        var newTab = new CodexMenubarItem { Header = "New tab", Shortcut = "Cmd+T" };
        newTab.ItemSelected += (_, args) => status.Text = $"ItemSelected: {args.Header} via {args.Source}.";

        var compact = new CodexMenubarCheckboxItem { Header = "Compact mode", IsChecked = true };
        compact.ItemSelected += (_, args) =>
        {
            status.Text = $"ItemSelected: {args.Header} checked={args.IsChecked} close={args.DidCloseOnSelect}.";
        };

        var file = new CodexMenubarMenu
        {
            Header = "File",
            Items =
            {
                newTab,
                new CodexMenubarItem { Header = "New window", Shortcut = "Cmd+N" },
                new CodexMenubarSeparator(),
                new CodexMenubarItem
                {
                    Header = "Share",
                    Items =
                    {
                        new CodexMenubarItem { Header = "Copy link" },
                        new CodexMenubarItem { Header = "Export markdown" }
                    }
                }
            }
        };
        var view = new CodexMenubarMenu
        {
            Header = "View",
            Items =
            {
                compact,
                new CodexMenubarCheckboxItem { Header = "Show full URLs" },
                new CodexMenubarSeparator(),
                new CodexMenubarItem { Header = "Reload", Shortcut = "Cmd+R" }
            }
        };
        var menubar = new CodexMenubar
        {
            Loop = true,
            Items =
            {
                file,
                BuildMenubarEditMenu(includeNestedFind: true),
                view
            }
        };
        menubar.OpenMenu(file);

        var handoffFile = BuildMenubarFileMenu();
        var handoffView = BuildMenubarViewMenu();
        var handoff = new CodexMenubar
        {
            Size = CodexControlSize.Small,
            Loop = true,
            Items =
            {
                handoffFile,
                handoffView,
                BuildMenubarProfilesMenu()
            }
        };
        handoff.OpenMenu(handoffView);

        var blocked = new CodexMenubar
        {
            IsLoading = true,
            Items =
            {
                BuildMenubarFileMenu(),
                BuildMenubarViewMenu()
            }
        };

        return new Grid
        {
            ColumnDefinitions =
            {
                new ColumnDefinition(GridLength.Star),
                new ColumnDefinition(GridLength.Star)
            },
            RowDefinitions =
            {
                new RowDefinition(GridLength.Auto),
                new RowDefinition(GridLength.Auto)
            },
            ColumnSpacing = 14,
            RowSpacing = 16,
            Children =
            {
                new StackPanel
                {
                    Spacing = 10,
                    Children =
                    {
                        status,
                        menubar
                    }
                },
                GridCell(handoff, row: 0, column: 1),
                GridCell(blocked, row: 1, column: 0)
            }
        };
    }

