    private static CodexMenubarMenu BuildMenubarEditMenu(bool includeNestedFind = false)
    {
        var edit = new CodexMenubarMenu
        {
            Header = "Edit",
            Items =
            {
                new CodexMenubarItem { Header = "Undo", Shortcut = "Cmd+Z" },
                new CodexMenubarItem { Header = "Redo", Shortcut = "Shift+Cmd+Z" },
                new CodexMenubarSeparator()
            }
        };

        if (includeNestedFind)
        {
            edit.Items.Add(new CodexMenubarItem
            {
                Header = "Find",
                IsSubMenuOpen = true,
                Items =
                {
                    new CodexMenubarItem { Header = "Search the web" },
                    new CodexMenubarSeparator(),
                    new CodexMenubarItem { Header = "Find", Shortcut = "Cmd+F" },
                    new CodexMenubarItem { Header = "Find next", Shortcut = "Cmd+G" }
                }
            });
            edit.Items.Add(new CodexMenubarSeparator());
        }

        edit.Items.Add(new CodexMenubarItem { Header = "Cut" });
        edit.Items.Add(new CodexMenubarItem { Header = "Copy" });
        edit.Items.Add(new CodexMenubarItem { Header = "Paste" });
        return edit;
    }

