    private static Control BuildAccordionInteractionPreview()
    {
        var status = Muted("Open values update after trigger activation.");
        var routing = new CodexAccordionItem
        {
            Value = "routing",
            Header = "Routing",
            IsOpen = true,
            Content = Muted("This is the initially open single-mode item.")
        };
        var billing = new CodexAccordionItem
        {
            Value = "billing",
            Header = "Billing",
            Content = Muted("Programmatic open closes Routing in single mode.")
        };
        var audit = new CodexAccordionItem
        {
            Value = "audit",
            Header = "Audit",
            IsEnabled = false,
            Content = Muted("Disabled triggers remain skipped.")
        };
        var single = new CodexAccordion
        {
            IsCollapsible = true,
            Items =
            {
                routing,
                billing,
                audit
            }
        };

        single.ValueChanged += (_, args) =>
        {
            var value = args.NewValues.Count == 0 ? "none" : string.Join(", ", args.NewValues);
            var changed = string.IsNullOrWhiteSpace(args.ChangedValue) ? "none" : args.ChangedValue;
            status.Text = $"Open values: {value} · changed {changed} · {args.Source}";
        };

        var openBilling = new CodexButton
        {
            Content = "Open billing",
            Size = CodexControlSize.Small,
            HorizontalAlignment = HorizontalAlignment.Left
        };
        openBilling.Click += (_, _) => billing.IsOpen = true;

        var collapseAll = new CodexButton
        {
            Content = "Collapse all",
            Size = CodexControlSize.Small,
            Variant = CodexControlVariant.Secondary,
            HorizontalAlignment = HorizontalAlignment.Left
        };
        collapseAll.Click += (_, _) =>
        {
            routing.IsOpen = false;
            billing.IsOpen = false;
        };

        return new Grid
        {
            ColumnDefinitions =
            {
                new ColumnDefinition(GridLength.Star),
                new ColumnDefinition(GridLength.Star)
            },
            ColumnSpacing = 14,
            Children =
            {
                new StackPanel
                {
                    Spacing = 12,
                    Children =
                    {
                        single,
                        status,
                        new StackPanel
                        {
                            Orientation = Orientation.Horizontal,
                            Spacing = 8,
                            Children =
                            {
                                openBilling,
                                collapseAll
                            }
                        }
                    }
                },
                SecondColumn(new CodexAccordion
                {
                    Type = CodexAccordionType.Multiple,
                    Size = CodexControlSize.Small,
                    Items =
                    {
                        new CodexAccordionItem
                        {
                            Value = "multi-routes",
                            Header = "Multiple routes",
                            IsOpen = true,
                            Content = Muted("Independent toggle remains open.")
                        },
                        new CodexAccordionItem
                        {
                            Value = "multi-limits",
                            Header = "Multiple limits",
                            IsOpen = true,
                            Content = Muted("The second item can stay open at the same time.")
                        }
                    }
                })
            }
        };
    }

