    private static Control BuildKbdInteractionPreview()
    {
        var status = Muted("Shortcut: Cmd + K.");
        var first = new CodexKbd { Content = "Cmd", Size = CodexControlSize.Small };
        var second = new CodexKbd { Content = "K", Size = CodexControlSize.Small };
        var sequenceStep = 0;
        var switchSequence = new CodexButton
        {
            Content = "Switch shortcut",
            Size = CodexControlSize.Small,
            Variant = CodexControlVariant.Secondary
        };
        switchSequence.Click += (_, _) =>
        {
            sequenceStep = (sequenceStep + 1) % 3;
            switch (sequenceStep)
            {
                case 1:
                    first.Content = "Esc";
                    second.Content = null;
                    status.Text = "Shortcut: Esc.";
                    break;
                case 2:
                    first.Content = "Shift";
                    second.Content = "P";
                    status.Text = "Shortcut: Shift + P.";
                    break;
                default:
                    first.Content = "Cmd";
                    second.Content = "K";
                    status.Text = "Shortcut: Cmd + K.";
                    break;
            }
        };

        var toggleSize = new CodexButton
        {
            Content = "Toggle density",
            Size = CodexControlSize.Small,
            Variant = CodexControlVariant.Ghost
        };
        toggleSize.Click += (_, _) =>
        {
            first.Size = first.Size == CodexControlSize.Small ? CodexControlSize.Large : CodexControlSize.Small;
            second.Size = first.Size;
            status.Text = $"Shortcut density changed to {first.Size}.";
        };

        return new Grid
        {
            ColumnDefinitions =
            {
                new ColumnDefinition(GridLength.Star),
                new ColumnDefinition(GridLength.Star)
            },
            RowDefinitions =
            {
                new RowDefinition(GridLength.Auto),
                new RowDefinition(GridLength.Auto)
            },
            ColumnSpacing = 16,
            RowSpacing = 14,
            Children =
            {
                new CodexField
                {
                    Label = "Shortcut sequence",
                    Description = "Host state can replace shortcut tokens while size classes stay synchronized.",
                    Content = new StackPanel
                    {
                        Spacing = 10,
                        Children =
                        {
                            status,
                            new CodexKbdGroup
                            {
                                Size = CodexControlSize.Small,
                                Items =
                                {
                                    first,
                                    second
                                }
                            },
                            new StackPanel
                            {
                                Orientation = Orientation.Horizontal,
                                Spacing = 8,
                                Children =
                                {
                                    switchSequence,
                                    toggleSize
                                }
                            }
                        }
                    }
                },
                GridCell(new CodexField
                {
                    Label = "Command hint composition",
                    Description = "Kbd tokens align with command rows and trailing shortcuts.",
                    Content = new CodexCommand
                    {
                        Content = new CodexCommandList
                        {
                            Items =
                            {
                                new CodexCommandItem { Content = "Open command palette", Shortcut = "Cmd K", IsActive = true },
                                new CodexCommandItem { Content = "Switch provider", Shortcut = "Shift P" }
                            }
                        }
                    }
                }, row: 0, column: 1),
                GridCell(new CodexField
                {
                    Label = "Chord sequence",
                    Description = "Multi-step shortcuts keep fixed token spacing.",
                    Content = new CodexKbdGroup
                    {
                        Size = CodexControlSize.Small,
                        Items =
                        {
                            new CodexKbd { Content = "Cmd", Size = CodexControlSize.Small },
                            new CodexKbd { Content = "K", Size = CodexControlSize.Small },
                            new CodexKbd { Content = "then", Size = CodexControlSize.Small },
                            new CodexKbd { Content = "P", Size = CodexControlSize.Small }
                        }
                    }
                }, row: 1, column: 0),
                GridCell(new CodexField
                {
                    Label = "Disabled host",
                    Description = "Shortcut hints remain readable inside disabled controls.",
                    Content = new CodexButton
