    private static Control BuildDialogInteractionPreview()
    {
        var trigger = new CodexButton
        {
            Content = "Open delete dialog",
            Size = CodexControlSize.Small
        };
        var status = Muted("OpenChanged: dialog starts closed.");
        var dialog = new CodexDialog
        {
            Trigger = trigger,
            Title = "Delete provider?",
            Description = "DismissCommand, Escape, outside pointer, and close button share the same close path.",
            RestoreFocusElement = trigger,
            Content = new StackPanel
            {
                Spacing = 10,
                Children =
                {
                    new CodexAlert
                    {
                        Icon = "!",
                        Title = "This action affects routing.",
                        Description = "The overlay remains mounted so exit classes can animate.",
                        Variant = CodexControlVariant.Warning
                    },
                    new CodexField
                    {
                        Label = "Audit note",
                        Content = new CodexTextarea { MinHeight = 76, PlaceholderText = "Optional reason" }
                    }
                }
            },
            Action = new StackPanel
            {
                Orientation = Orientation.Horizontal,
                Spacing = 8,
                HorizontalAlignment = HorizontalAlignment.Right,
                Children =
                {
                    new CodexButton { Content = "Cancel", Variant = CodexControlVariant.Outline, Size = CodexControlSize.Small },
                    new CodexButton { Content = "Delete", Variant = CodexControlVariant.Destructive, Size = CodexControlSize.Small }
                }
            }
        };
        dialog.OpenChanged += (_, args) =>
        {
            status.Text = args.IsOpen ? "OpenChanged: dialog opened from the trigger." : "OpenChanged: dialog closed.";
        };
        dialog.RestoreFocusRequested += (_, _) =>
        {
            status.Text = "Dismissed and requested focus restoration to the trigger.";
        };

        var dismiss = new CodexButton
        {
            Content = "Dismiss command",
            Variant = CodexControlVariant.Secondary,
            Size = CodexControlSize.Small
        };
        dismiss.Click += (_, _) =>
        {
            if (dialog.DismissCommand?.CanExecute(null) == true)
            {
                dialog.DismissCommand.Execute(null);
            }
        };

        var manualDialog = new CodexDialog
        {
            Title = "Manual close policy",
            Description = "Escape and outside pointer are disabled; host code owns dismissal.",
            IsOpen = true,
            CloseOnEscape = false,
            DismissOnOutsidePointer = false,
            IsCloseVisible = false,
            Content = new StackPanel
            {
                Spacing = 8,
                Children =
                {
                    new CodexBadge { Content = "manual", Variant = CodexControlVariant.Outline },
                    Muted("CloseOnEscape=false and DismissOnOutsidePointer=false.")
                }
            },
            Action = new CodexButton { Content = "Apply", Size = CodexControlSize.Small }
        };

        var closedDialog = new CodexDialog
        {
            Title = "Closed exit state",
            Description = "Closed class drives exit styling while the surface remains inspectable.",
            IsOpen = false,
            Content = Muted("Reopen to exercise the open class and action row."),
            Action = new CodexButton { Content = "Confirm", Size = CodexControlSize.Small }
        };
        var toggleClosed = new CodexButton
        {
            Content = "Toggle closed sample",
            Variant = CodexControlVariant.Secondary,
            Size = CodexControlSize.Small
        };
        toggleClosed.Click += (_, _) =>
        {
            closedDialog.IsOpen = !closedDialog.IsOpen;
        };

        return new Grid
        {
            ColumnDefinitions =
            {
                new ColumnDefinition(GridLength.Star),
                new ColumnDefinition(GridLength.Star)
            },
            RowDefinitions =
            {
                new RowDefinition(GridLength.Auto),
                new RowDefinition(GridLength.Auto)
            },
            ColumnSpacing = 16,
            RowSpacing = 14,
            Children =
            {
                new StackPanel
                {
                    Spacing = 10,
                    Children =
                    {
                        status,
                        dialog,
                        dismiss
                    }
                },
                GridCell(manualDialog, row: 0, column: 1),
                GridCell(new StackPanel
                {
                    Spacing = 10,
                    Children =
                    {
                        closedDialog,
                        toggleClosed
                    }
                }, row: 1, column: 0),
                GridCell(new CodexDialog
                {
                    Title = "Action close surface",
                    Description = "Action buttons stay in the dialog slot while the close control routes through Dismiss.",
                    IsOpen = true,
                    CloseContent = "Esc",
                    Content = Muted("Close content can mirror the keyboard dismissal affordance."),
                    Action = new StackPanel
                    {
                        Orientation = Orientation.Horizontal,
                        Spacing = 8,
                        HorizontalAlignment = HorizontalAlignment.Right,
                        Children =
                        {
                            new CodexButton { Content = "Keep", Variant = CodexControlVariant.Secondary, Size = CodexControlSize.Small },
                            new CodexButton { Content = "Archive", Variant = CodexControlVariant.Destructive, Size = CodexControlSize.Small }
                        }
                    }
                }, row: 1, column: 1)
            }
        };
