    private static Control BuildSheetInteractionPreview()
    {
        var trigger = new CodexButton
        {
            Content = "Toggle sheet",
            Size = CodexControlSize.Small
        };
        var status = Muted("Sheet is open on the right edge.");
        var sheet = new CodexSheet
        {
            Trigger = trigger,
            Title = "Route filters",
            Description = "Dismiss, Escape, outside pointer, and focus return reuse the dialog contract.",
            Side = CodexSheetSide.Right,
            Width = 360,
            IsOpen = true,
            RestoreFocusElement = trigger,
            Content = new StackPanel
            {
                Spacing = 10,
                Children =
                {
                    new CodexField
                    {
                        Label = "Provider",
                        Content = new CodexTextBox { Text = "OpenAI" }
                    },
                    new CodexCheckBox { Content = "Show degraded routes", IsChecked = true },
                    new CodexAlert
                    {
                        Title = "Mounted exit state",
                        Description = "Closing sets IsOpen=false and keeps the sheet available for exit motion.",
                        Variant = CodexControlVariant.Secondary
                    }
                }
            },
            Action = new StackPanel
            {
                Orientation = Orientation.Horizontal,
                Spacing = 8,
                HorizontalAlignment = HorizontalAlignment.Right,
                Children =
                {
                    new CodexButton { Content = "Reset", Variant = CodexControlVariant.Secondary, Size = CodexControlSize.Small },
                    new CodexButton { Content = "Apply", Size = CodexControlSize.Small }
                }
            }
        };
        sheet.RestoreFocusRequested += (_, _) =>
        {
            status.Text = "Sheet dismissed and requested focus restoration to the trigger.";
        };
        sheet.OpenChanged += (_, args) =>
        {
            status.Text = args.IsOpen
                ? $"OpenChanged: sheet opened on the {sheet.Side.ToString().ToLowerInvariant()} edge."
                : "OpenChanged: sheet closed.";
        };

        var dismiss = new CodexButton
        {
            Content = "Dismiss command",
            Size = CodexControlSize.Small,
            Variant = CodexControlVariant.Secondary
        };
        dismiss.Click += (_, _) =>
        {
            if (sheet.DismissCommand?.CanExecute(null) == true)
            {
                sheet.DismissCommand.Execute(null);
            }
        };

        var cycleSide = new CodexButton
        {
            Content = "Cycle side",
            Size = CodexControlSize.Small,
            Variant = CodexControlVariant.Ghost
        };
        cycleSide.Click += (_, _) =>
        {
            sheet.Side = sheet.Side switch
            {
                CodexSheetSide.Right => CodexSheetSide.Bottom,
                CodexSheetSide.Bottom => CodexSheetSide.Left,
                CodexSheetSide.Left => CodexSheetSide.Top,
                _ => CodexSheetSide.Right
            };
            status.Text = $"Sheet side changed to {sheet.Side}; edge slide classes updated.";
        };

        var manualPolicy = new CodexButton
        {
            Content = "Manual policy",
            Size = CodexControlSize.Small,
            Variant = CodexControlVariant.Ghost
        };
        manualPolicy.Click += (_, _) =>
        {
            sheet.CloseOnEscape = !sheet.CloseOnEscape;
            sheet.DismissOnOutsidePointer = sheet.CloseOnEscape;
            status.Text = sheet.CloseOnEscape
                ? "Escape and outside pointer dismissal are enabled."
                : "Escape and outside pointer dismissal are disabled for host-managed close.";
        };

        return new Grid
        {
            ColumnDefinitions =
            {
                new ColumnDefinition(GridLength.Star),
                new ColumnDefinition(GridLength.Star)
            },
            RowDefinitions =
            {
                new RowDefinition(GridLength.Auto),
                new RowDefinition(GridLength.Auto)
            },
            ColumnSpacing = 16,
            RowSpacing = 14,
            Children =
            {
                new StackPanel
                {
                    Spacing = 10,
                    Children =
                    {
                        status,
                        new Grid
                        {
                            Height = 280,
                            Children =
                            {
                                sheet
                            }
                        },
                        new StackPanel
                        {
                            Orientation = Orientation.Horizontal,
                            Spacing = 8,
                            Children =
                            {
                                dismiss,
                                cycleSide,
                                manualPolicy
                            }
                        }
                    }
                },
                GridCell(new CodexSheet
                {
                    IsOpen = true,
                    Title = "Manual close",
                    Description = "Outside pointer and Escape can be disabled for transactional flows.",
                    Side = CodexSheetSide.Left,
                    Width = 330,
                    CloseOnEscape = false,
                    DismissOnOutsidePointer = false,
                    IsCloseVisible = false,
                    Content = Muted("Host code controls when this sheet closes."),
                    Action = new CodexButton { Content = "Apply", Size = CodexControlSize.Small }
                }, row: 0, column: 1),
                GridCell(new CodexSheet
                {
                    Trigger = new CodexButton
                    {
                        Content = "Open closed sheet",
                        Size = CodexControlSize.Small,
                        Variant = CodexControlVariant.Secondary
                    },
                    Title = "Closed edge state",
                    Description = "Closed class preserves the side-specific exit transform.",
                    Side = CodexSheetSide.Bottom,
                    IsOpen = false,
                    Content = Muted("Useful for reduced-motion and snapshot checks.")
                }, row: 1, column: 0),
                GridCell(new CodexSheet
                {
                    IsOpen = true,
                    Title = "No close button",
                    Description = "showCloseButton=false maps to IsCloseVisible=false.",
                    Side = CodexSheetSide.Top,
                    IsCloseVisible = false,
                    Content = new StackPanel
                    {
                        Spacing = 8,
                        Children =
                        {
                            Muted("The action slot can provide the only close affordance."),
                            new CodexButton { Content = "Done", Size = CodexControlSize.Small, HorizontalAlignment = HorizontalAlignment.Left }
                        }
                    }
                }, row: 1, column: 1)
            }
        };
    }

