    private static Control BuildPopoverInteractionPreview()
    {
        var trigger = new CodexButton
        {
            Content = "Usage trigger",
            Size = CodexControlSize.Small
        };
        var status = Muted("OpenChanged: popover starts closed.");
        var popover = new CodexPopover
        {
            Trigger = trigger,
            Title = "Usage window",
            Description = "DismissCommand, Escape, and outside pointer share the same close path.",
            IsArrowVisible = true,
            RestoreFocusElement = trigger,
            Content = new StackPanel
            {
                Spacing = 8,
                Children =
                {
                    new CodexProgress { Minimum = 0, Maximum = 100, Value = 72, Variant = CodexControlVariant.Warning },
                    Muted("72% of the monthly budget is used.")
                }
            },
            Action = new CodexButton { Content = "Open billing", Size = CodexControlSize.Small }
        };
        popover.OpenChanged += (_, args) =>
        {
            status.Text = args.IsOpen ? "OpenChanged: popover opened from the trigger." : "OpenChanged: popover closed.";
        };
        popover.RestoreFocusRequested += (_, _) =>
        {
            status.Text = "Dismissed and requested focus restoration to the trigger.";
        };

        var dismiss = new CodexButton
        {
            Content = "Dismiss command",
            Variant = CodexControlVariant.Secondary,
            Size = CodexControlSize.Small
        };
        dismiss.Click += (_, _) =>
        {
            if (popover.DismissCommand?.CanExecute(null) == true)
            {
                popover.DismissCommand.Execute(null);
            }
        };

        var policy = new CodexPopover
        {
            Title = "Persistent panel",
            Description = "Escape and outside pointer are disabled for manual host control.",
            IsOpen = true,
            CloseOnEscape = false,
            DismissOnOutsidePointer = false,
            IsCloseVisible = false,
            Content = new StackPanel
            {
                Spacing = 8,
                Children =
                {
                    new CodexBadge { Content = "manual", Variant = CodexControlVariant.Outline },
                    Muted("The host controls open state and focus restoration.")
                }
            },
            Action = new CodexButton { Content = "Apply", Size = CodexControlSize.Small }
        };

        var closed = new CodexPopover
        {
            Title = "Closed popover",
            Description = "Closed class stays mounted for exit styling.",
            IsOpen = false,
            Content = Muted("Toggle open state without replacing the surface.")
        };
        var toggleClosed = new CodexButton
        {
            Content = "Toggle closed sample",
            Variant = CodexControlVariant.Secondary,
            Size = CodexControlSize.Small
        };
        toggleClosed.Click += (_, _) => closed.IsOpen = !closed.IsOpen;

        return new Grid
        {
            ColumnDefinitions =
            {
                new ColumnDefinition(GridLength.Star),
                new ColumnDefinition(GridLength.Star)
            },
            RowDefinitions =
            {
                new RowDefinition(GridLength.Auto),
                new RowDefinition(GridLength.Auto)
            },
            ColumnSpacing = 16,
            RowSpacing = 14,
            Children =
            {
                new StackPanel
                {
                    Spacing = 10,
                    Children =
                    {
                        status,
                        popover,
                        dismiss
                    }
                },
                GridCell(policy, row: 0, column: 1),
                GridCell(new StackPanel
                {
                    Spacing = 10,
                    Children =
                    {
                        closed,
                        toggleClosed
                    }
                }, row: 1, column: 0),
                GridCell(new CodexPopover
                {
                    Title = "Action content",
                    Description = "Action slot remains mounted while close content routes through Dismiss.",
                    IsOpen = true,
                    CloseContent = "Esc",
                    Content = Muted("Popover body can contain any Codex component."),
                    Action = new StackPanel
                    {
                        Orientation = Orientation.Horizontal,
                        Spacing = 8,
                        Children =
                        {
                            new CodexButton { Content = "Later", Variant = CodexControlVariant.Secondary, Size = CodexControlSize.Small },
                            new CodexButton { Content = "Open", Size = CodexControlSize.Small }
                        }
                    }
                }, row: 1, column: 1)
            }
        };
    }

