    private static Control BuildTableInteractionPreview()
    {
        var status = Muted("Select a row to move the selected class and restart table content motion.");
        var version = 0;
        var gpt = (CodexTableRow)TableDataRow("gpt-5", "Responses", "42.7K", "Primary", true);
        var claude = (CodexTableRow)TableDataRow("claude-sonnet", "Claude", "18.3K", "Fallback", false);
        var mini = (CodexTableRow)TableDataRow("o4-mini", "Chat", "7.1K", "Disabled", false, isEnabled: false);
        var rows = new[] { gpt, claude, mini };
        var table = new CodexTable
        {
            IsStriped = true,
            IsHoverable = true,
            TransitionKey = "providers-initial",
            Content = new StackPanel
            {
                Spacing = 0,
                Children =
                {
                    TableHeaderRow(),
                    new CodexTableBody
                    {
                        Items =
                        {
                            gpt,
                            claude,
                            mini
                        }
                    },
                    new CodexTableCaption { Content = "Pointer row selection updates selected state without rebuilding table chrome." }
                }
            }
        };

        void SelectRow(CodexTableRow row, string model)
        {
            if (!row.IsEnabled)
            {
                status.Text = "Disabled rows ignore pointer selection.";
                return;
            }

            foreach (var item in rows)
            {
                item.IsSelected = ReferenceEquals(item, row);
            }

            table.TransitionKey = $"{model}-{++version}";
            status.Text = $"{model} selected; sibling rows cleared and content transition restarted.";
        }

        void SelectRowFromPointer(PointerReleasedEventArgs args, CodexTableRow row, string model)
        {
            if (args.GetCurrentPoint(row).Properties.PointerUpdateKind != PointerUpdateKind.LeftButtonReleased)
            {
                return;
            }

            SelectRow(row, model);
            args.Handled = true;
        }

        gpt.PointerReleased += (_, args) => SelectRowFromPointer(args, gpt, "gpt-5");
        claude.PointerReleased += (_, args) => SelectRowFromPointer(args, claude, "claude-sonnet");
        mini.PointerReleased += (_, args) => SelectRowFromPointer(args, mini, "o4-mini");

        var density = new CodexButton
        {
            Content = "Toggle density",
            Size = CodexControlSize.Small,
            Variant = CodexControlVariant.Secondary
        };
        density.Click += (_, _) =>
        {
            table.IsCompact = !table.IsCompact;
            table.TransitionKey = $"density-{++version}";
            status.Text = table.IsCompact
                ? "Compact density applied; row selection state stayed intact."
                : "Default density restored; row selection state stayed intact.";
        };

        var hover = new CodexButton
        {
            Content = "Toggle hover",
            Size = CodexControlSize.Small,
            Variant = CodexControlVariant.Ghost
        };
        hover.Click += (_, _) =>
        {
            table.IsHoverable = !table.IsHoverable;
            status.Text = table.IsHoverable
                ? "Hover feedback enabled for selectable rows."
                : "Hover feedback disabled while selection state remains visible.";
        };

        return new Grid
        {
            ColumnDefinitions =
            {
                new ColumnDefinition(GridLength.Star),
                new ColumnDefinition(GridLength.Star)
            },
            RowDefinitions =
            {
                new RowDefinition(GridLength.Auto),
                new RowDefinition(GridLength.Auto)
            },
            ColumnSpacing = 16,
            RowSpacing = 14,
            Children =
            {
                new CodexField
                {
                    Label = "Selectable rows",
                    Description = "Pointer release selects one row, clears siblings, and updates the transition key.",
                    Content = new StackPanel
                    {
                        Spacing = 10,
                        Children =
                        {
                            status,
                            table,
                            new StackPanel
                            {
                                Orientation = Orientation.Horizontal,
                                Spacing = 8,
                                Children =
                                {
                                    density,
                                    hover
                                }
                            }
                        }
                    }
                },
                GridCell(new CodexField
                {
                    Label = "Loading refresh surface",
                    Description = "Refresh actions can change TransitionKey while leaving the table scaffold mounted.",
                    Content = new CodexTable
                    {
                        IsCompact = true,
                        IsStriped = true,
                        TransitionKey = "refreshing",
                        Content = new StackPanel
                        {
                            Spacing = 0,
                            Children =
                            {
                                TableHeaderRow(),
                                TableDataRow("gpt-5", "Responses", "43.2K", "Refreshing", true),
                                TableDataRow("claude-sonnet", "Claude", "18.8K", "Queued", false)
                            }
                        }
                    }
                }, row: 0, column: 1),
                GridCell(new CodexField
                {
                    Label = "Disabled selection guard",
                    Description = "Disabled rows keep row geometry but do not become selected.",
                    Content = new CodexTable
                    {
                        IsHoverable = true,
                        Content = new StackPanel
                        {
                            Spacing = 0,
                            Children =
                            {
                                TableHeaderRow(),
                                TableDataRow("locked-model", "Responses", "0", "Disabled", false, isEnabled: false)
                            }
                        }
                    }
                }, row: 1, column: 0),
                GridCell(new CodexField
                {
                    Label = "Alignment and footer",
                    Description = "Cell alignment and footer rows stay stable while data refreshes.",
                    Content = new CodexTable
                    {
                        IsStriped = true,
                        Content = new StackPanel
                        {
                            Spacing = 0,
                            Children =
                            {
                                TableHeaderRow(),
                                TableDataRow("total", "3 routes", "69.1K", "Healthy", false),
                                new CodexTableFooter
                                {
                                    Content = TableGrid(
                                        TableCell("Updated", 0),
                                        TableCell("just now", 1),
                                        TableCell("100%", 2, CodexTableCellAlignment.Right),
                                        TableCell("Ready", 3))
                                }
                            }
                        }
                    }
                }, row: 1, column: 1)
            }
        };
    }

