    private static Control BuildAspectRatioInteractionPreview()
    {
        var status = Muted("Change the ratio, switch fit mode, or toggle content.");
        var aspectRatio = AspectRatioMedia(
            "Interactive media",
            "RatioChanged updates this status.",
            "16:9",
            16d / 9d,
            360,
            accentKey: CodexSwitchResourceKeys.PrimaryBrush);

        aspectRatio.RatioChanged += (_, args) =>
        {
            status.Text = $"RatioChanged: {args.RatioText} ({args.OldRatio:0.###} -> {args.NewRatio:0.###}).";
        };

        var video = new CodexButton { Content = "16:9", Size = CodexControlSize.Small, Variant = CodexControlVariant.Secondary };
        video.Click += (_, _) => aspectRatio.Ratio = 16d / 9d;

        var square = new CodexButton { Content = "1:1", Size = CodexControlSize.Small, Variant = CodexControlVariant.Secondary };
        square.Click += (_, _) => aspectRatio.Ratio = 1d;

        var portrait = new CodexButton { Content = "9:16", Size = CodexControlSize.Small, Variant = CodexControlVariant.Secondary };
        portrait.Click += (_, _) => aspectRatio.Ratio = 9d / 16d;

        var invalid = new CodexButton { Content = "Invalid", Size = CodexControlSize.Small, Variant = CodexControlVariant.Ghost };
        invalid.Click += (_, _) => aspectRatio.Ratio = -1d;

        var fit = new CodexButton { Content = "Fit: width", Size = CodexControlSize.Small, Variant = CodexControlVariant.Secondary };
        fit.Click += (_, _) =>
        {
            aspectRatio.FitMode = aspectRatio.FitMode switch
            {
                CodexAspectRatioFitMode.Width => CodexAspectRatioFitMode.Height,
                CodexAspectRatioFitMode.Height => CodexAspectRatioFitMode.Contain,
                _ => CodexAspectRatioFitMode.Width
            };
            fit.Content = $"Fit: {aspectRatio.FitMode.ToString().ToLowerInvariant()}";
            status.Text = $"FitMode switched to {aspectRatio.FitMode}.";
        };

        var toggleContent = new CodexButton { Content = "Hide content", Size = CodexControlSize.Small, Variant = CodexControlVariant.Secondary };
        toggleContent.Click += (_, _) =>
        {
            var shouldHide = aspectRatio.Content is not null;
            aspectRatio.Content = shouldHide
                ? null
                : AspectRatioMediaContent("Interactive media", "Content restored into the same viewport.", "restored", CodexSwitchResourceKeys.PrimaryBrush);
            toggleContent.Content = shouldHide ? "Restore content" : "Hide content";
            status.Text = shouldHide
                ? "Content removed; empty and RatioText placeholder state is visible."
                : "Content restored; has-content state is active again.";
        };

        return new Grid
        {
            ColumnDefinitions =
            {
                new ColumnDefinition(GridLength.Star),
                new ColumnDefinition(GridLength.Star)
            },
            ColumnSpacing = 16,
            Children =
            {
                new CodexField
                {
                    Label = "Ratio event path",
                    Description = "Ratio, fit, and content mutations stay component-owned.",
                    Content = new StackPanel
                    {
                        Spacing = 10,
                        Children =
                        {
                            status,
                            aspectRatio,
                            new StackPanel
                            {
                                Orientation = Orientation.Horizontal,
                                Spacing = 8,
                                Children =
                                {
                                    video,
                                    square,
                                    portrait,
                                    invalid
                                }
                            },
                            new StackPanel
                            {
                                Orientation = Orientation.Horizontal,
                                Spacing = 8,
                                Children =
                                {
                                    fit,
                                    toggleContent
                                }
                            }
                        }
                    }
                },
                SecondColumn(AspectRatioField(
                    "Hover and empty guard",
                    "Pointer hover animates border state; invalid ratios normalize to a square placeholder.",
                    new CodexAspectRatio
                    {
                        Ratio = double.NaN,
                        Width = 230,
                        Size = CodexControlSize.Small
                    }))
            }
        };
    }

