        };
    }

    private static CodexAspectRatio AspectRatioMedia(
        string title,
        string description,
        string badge,
        double ratio,
        double width,
        CodexAspectRatioFitMode fitMode = CodexAspectRatioFitMode.Width,
        double height = double.NaN,
        CodexControlSize size = CodexControlSize.Medium,
        string accentKey = CodexSwitchResourceKeys.PrimaryBrush)
    {
        var aspectRatio = new CodexAspectRatio
        {
            Ratio = ratio,
            Width = width,
            FitMode = fitMode,
            Size = size,
            Content = AspectRatioMediaContent(title, description, badge, accentKey)
        };

        if (!double.IsNaN(height))
        {
            aspectRatio.Height = height;
        }

        return aspectRatio;
    }

    private static Control AspectRatioMediaContent(string title, string description, string badge, string accentKey)
    {
        return new Border
        {
            Background = ThemeBrush(CodexSwitchResourceKeys.MutedBrush),
            Child = new Grid
            {
                Children =
                {
                    new Border
                    {
                        Width = 6,
                        HorizontalAlignment = HorizontalAlignment.Left,
                        Background = ThemeBrush(accentKey)
                    },
                    new StackPanel
                    {
                        Margin = new Thickness(22, 16, 16, 16),
                        Spacing = 8,
                        VerticalAlignment = VerticalAlignment.Bottom,
                        Children =
                        {
