        refresh.Click += (_, _) =>
        {
            version++;
            var value = version % 2 == 0 ? "42.7K" : "48.9K";
            tokens.Value = Text(value, CodexTextRole.Subtitle);
            tokens.Detail = version % 2 == 0 ? "+18% from yesterday" : "+31% after routing change";
