                    {
                        Spacing = 10,
                        Children =
                        {
                            status,
                            new Grid
                            {
                                Height = 188,
                                Children =
                                {
                                    overlay
                                }
                            },
                            new StackPanel
                            {
                                Orientation = Orientation.Horizontal,
                                Spacing = 8,
                                Children =
                                {
                                    reopen,
                                    toggleScrim,
                                    manualPolicy
                                }
                            }
                        }
                    }
                },
                GridCell(new CodexField
                {
                    Label = "Manual policy",
                    Description = "Host-managed layers can disable Escape and outside-pointer dismissal.",
                    Content = new Grid
                    {
                        Height = 160,
                        Children =
                        {
                            new CodexOverlay
                            {
                                IsOpen = true,
