            TableCell(row?.Cost ?? string.Empty, 2, CodexTableCellAlignment.Right),
            TableCell(row?.Fallback ?? string.Empty, 3));
    }

    private static Grid PinnedTableGrid(params Control[] cells)
    {
        var grid = new Grid
        {
            ColumnDefinitions =
            {
