    private static string IconPath(string iconName)
    {
        return DocsIconBase + iconName;
    }

    private static string IconFileName(string? iconPath)
    {
        if (string.IsNullOrWhiteSpace(iconPath))
        {
            return "none";
        }

        var slashIndex = iconPath.LastIndexOf('/');
        return slashIndex >= 0 && slashIndex < iconPath.Length - 1
            ? iconPath[(slashIndex + 1)..]
            : iconPath;
    }

