    {
        return new CodexProviderCard
        {
            Header = Text(title, CodexTextRole.Body),
            Meta = ProviderCardMeta(isActive),
            Description = description,
            Icon = title.Length > 0 ? title[0].ToString() : "?",
            Status = new CodexBadge
            {
                Content = isEnabled ? "Healthy" : "Locked",
                Variant = isEnabled ? CodexControlVariant.Secondary : CodexControlVariant.Outline
            },
            Usage = new CodexMetric
            {
                Label = "Tokens",
                Value = Text(isActive ? "42.7K" : "7.1K", CodexTextRole.Body)
            },
            Actions = new CodexIconButton
            {
                Content = "...",
                Variant = CodexControlVariant.Ghost
            },
            IsActive = isActive,
            IsDragging = isDragging,
            IsEnabled = isEnabled
        };
    }

    private static CodexBadge ProviderCardMeta(bool isActive)
    {
        return new CodexBadge
        {
            Content = isActive ? "Active" : "Ready",
            Variant = isActive ? CodexControlVariant.Success : CodexControlVariant.Secondary
        };
    }

    private static Control OverlayState(string label, bool isOpen, bool hasScrim, int column)
    {
        var stack = new StackPanel
        {
            Spacing = 8,
            Children =
            {
                Muted(label),
                new Grid
                {
                    Height = 150,
                    Children =
                    {
                        new CodexOverlay
                        {
                            IsOpen = isOpen,
                            IsScrimVisible = hasScrim,
                            ScrimOpacity = hasScrim ? 0.36 : 0,
                            HorizontalContentAlignment = HorizontalAlignment.Center,
                            VerticalContentAlignment = VerticalAlignment.Center,
                            Content = new CodexCard
                            {
                                Width = 210,
                                Title = label,
                                Description = isOpen ? "Composed layer" : "Closed state",
                                Content = new CodexButton { Content = "Dismiss", Size = CodexControlSize.Small }
                            }
                        }
                    }
                }
            }
        };

        Grid.SetColumn(stack, column);
        return stack;
    }

    private static Control SheetState(string label, CodexSheetSide side, bool isOpen, int row, int column)
    {
        var stack = new StackPanel
        {
            Spacing = 8,
            Children =
            {
                Muted(label),
                new Grid
                {
                    Height = 178,
                    Children =
                    {
                        new CodexSheet
                        {
                            Trigger = isOpen
                                ? null
                                : new CodexButton
                                {
                                    Content = "Open sheet",
                                    Size = CodexControlSize.Small,
                                    Variant = CodexControlVariant.Secondary
                                },
                            Title = label,
                            Description = isOpen ? "Edge-mounted drawer" : "Closed edge state",
                            Side = side,
                            IsOpen = isOpen,
                            Width = side is CodexSheetSide.Left or CodexSheetSide.Right ? 260 : double.NaN,
                            Content = Muted($"Side={side}; mounted={isOpen}.")
                        }
                    }
                }
            }
        };

        Grid.SetRow(stack, row);
        Grid.SetColumn(stack, column);
        return stack;
    }

    private Border PreviewPanel(Control content)
    {
        return ThemedBorder(
            CodexSwitchResourceKeys.CardBrush,
            CodexSwitchResourceKeys.BorderBrush,
            new Thickness(1),
            new CornerRadius(8),
            new Thickness(22),
            content);
    }

    private static Control SectionHeader(string title, string description)
    {
        return new StackPanel
        {
            Spacing = 3,
            Children =
            {
                Text(title, CodexTextRole.Subtitle),
                Muted(description)
            }
        };
    }

    private static Control Stat(string label, string value, int column)
    {
        var stat = new StackPanel
        {
            Spacing = 5,
            Children =
            {
                Muted(label),
                Text(value, CodexTextRole.Subtitle)
            }
        };
        Grid.SetColumn(stat, column);
        return stat;
    }

    private static Control SecondColumn(Control control)
    {
        Grid.SetColumn(control, 1);
        return control;
    }

    private static Control SecondRow(Control control)
    {
        Grid.SetRow(control, 1);
        return control;
    }

    private static Control GridCell(Control control, int row, int column)
    {
        Grid.SetRow(control, row);
        Grid.SetColumn(control, column);
        return control;
    }

    private static Control SwitchRow(string label, CodexSwitch toggle)
    {
        return new Grid
        {
            ColumnDefinitions =
            {
                new ColumnDefinition(GridLength.Star),
                new ColumnDefinition(GridLength.Auto)
            },
            Children =
            {
                Muted(label),
                SecondColumn(toggle)
            }
        };
    }

    private static CodexText Text(string text, CodexTextRole role)
    {
        return new CodexText
        {
            Text = text,
            Role = role,
            TextWrapping = TextWrapping.Wrap
        };
    }

    private static CodexText Muted(string text)
    {
        return Text(text, CodexTextRole.Muted);
    }

    private static IBrush ThemeBrush(string key)
    {
        if (Application.Current?.TryFindResource(key, null, out var value) == true && value is IBrush brush)
        {
            return brush;
        }

        return Brushes.Transparent;
    }

    private sealed class DocsActionCommand(Action execute, Func<bool>? canExecute = null) : ICommand
    {
        public event EventHandler? CanExecuteChanged
        {
            add { }
            remove { }
        }

        public bool CanExecute(object? parameter)
        {
            return canExecute?.Invoke() ?? true;
        }

        public void Execute(object? parameter)
        {
            execute();
        }
    }

    private void ApplyTheme(CodexSwitchThemeMode mode)
    {
        _currentMode = mode;
        var options = mode == CodexSwitchThemeMode.Custom
            ? CodexSwitchThemeOptions.ShadcnDefault with
            {
                CustomPalette = CodexSwitchPalette.Light with
                {
                    Primary = "#FF2563EB",
                    Ring = "#FF2563EB"
                },
                Radius = 6
            }
            : CodexSwitchThemeOptions.ShadcnDefault;

        CodexSwitchThemeManager.Current.Apply(Application.Current!, mode, options);
        RefreshThemeSurfaces();
        RefreshTopbar(_activePage);
    }

    private void RefreshThemeSurfaces()
    {
        Background = ThemeBrush(CodexSwitchResourceKeys.BackgroundBrush);

        foreach (var (border, backgroundKey, borderKey) in _themedBorders)
        {
            ApplyThemeBorder(border, backgroundKey, borderKey);
        }
    }
}
